import merge from 'deepmerge';
/**
 * Define Stylelint configuration.
 */
export function setConfig(options = {}) {
    options = merge({
        toggles: {
            scss: true,
        },
        ignores: [],
    }, options);
    const baseConfig = {
        extends: ['stylelint-config-standard', 'stylelint-config-recess-order', 'stylelint-prettier/recommended'],
        // @todo Add `ignorePath` when it is supported in the new config format.
        //   https://github.com/stylelint/stylelint/issues/8345
        ignoreFiles: [...new Set([
                '**/.ddev/',
                '**/.docksal/',
                '**/.lando/',
                '**/config/',
                '**/default.*',
                '**/local.*',
                ...options.ignores,
            ])],
        rules: {
            'at-rule-empty-line-before': ['always', {
                    except: ['first-nested', 'blockless-after-blockless'],
                    ignore: ['after-comment'],
                }],
            'color-function-notation': ['modern', { ignore: 'with-var-inside' }],
            'comment-empty-line-before': ['always', {
                    except: ['first-nested'],
                    ignore: ['after-comment', 'stylelint-commands'],
                }],
            'no-duplicate-selectors': null,
            'number-max-precision': [10, {}],
            'prettier/prettier': [true, { printWidth: 240 }],
            'selector-class-pattern': '^([a-zA-Z][a-zA-Z0-9_]*)((-|_)+[a-zA-Z0-9_]+)*$',
            'selector-id-pattern': '^([a-zA-Z][a-zA-Z0-9_]*)((-|_)+[a-zA-Z0-9_]+)*$',
        },
        overrides: [],
    };
    if (options.toggles.scss) {
        baseConfig.overrides.push({
            files: ['**/*.scss'],
            extends: ['stylelint-config-standard-scss', 'stylelint-config-prettier-scss'],
            rules: {
                'no-descending-specificity': null,
                'scss/dollar-variable-empty-line-before': ['always', {
                        ignore: ['after-comment', 'after-dollar-variable', 'inside-single-line-block'],
                    }],
                'scss/double-slash-comment-empty-line-before': null,
            },
        });
    }
    return baseConfig;
}
